    Accepts any iterable of characters (including strings, lists, tuples, bytes).
    Returns a list of [character, count] pairs. Returns [] for empty or
    non‑iterable input.
    """
    try:
        iterator = iter(s)
    except TypeError:
        return []
    # Convert to list to allow checking emptiness without consuming iterator
    try:
        seq = list(iterator)
    except Exception:
        return []
    if not seq:
        return []
    result = []
    cur = seq[0]
    cnt = 1
    for ch in seq[1:]:
        if ch == cur:
            cnt += 1
        else:
            result.append([cur, cnt])
            cur = ch
            cnt = 1
    result.append([cur, cnt])
    return result

