def solve(tokens):
    """Evaluate an RPN expression with operators +, -, *, /.
    Numbers may have an optional leading '+' or '-'. Division truncates toward zero.
    """
    stack = []
    for t in tokens:
        # Determine if token is an integer (optional leading + or -)
        if (t and (t[0] == '+' or t[0] == '-') and t[1:].isdigit()) or t.isdigit():
            stack.append(int(t))
        else:
            # Operator
            b = stack.pop()
            a = stack.pop()
            if t == '+':
                res = a + b
            elif t == '-':
                res = a - b
            elif t == '*':
                res = a * b
            elif t == '/':
                # Truncate toward zero
                # Use integer division on absolute values then apply sign
                if b == 0:
                    raise ZeroDivisionError('division by zero')
                sign = -1 if (a * b) < 0 else 1
                res = abs(a) // abs(b)
                res = sign * res
            else:
                raise ValueError('unknown operator')
            stack.append(res)
    return stack[0] if stack else 0

