def solve(nums):
    # Return length of longest strictly increasing subsequence.
    # If input is not a list/tuple of numbers, treat as empty.
    if not isinstance(nums, (list, tuple)):
        return 0
    if not nums:
        return 0
    import bisect
    tails = []
    for x in nums:
        # ensure x is comparable; skip non-int/float values
        if not isinstance(x, (int, float)):
            continue
        idx = bisect.bisect_left(tails, x)
        if idx == len(tails):
            tails.append(x)
        else:
            tails[idx] = x
    return len(tails)
